    private void bumpIdentity(String table) {
        Long next = jdbc.queryForObject(
                "SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
    }
